import { expect, it } from 'vitest';
import { sortedScores } from '../src/sorted-scores';

it('keeps the caller array unchanged', () => {
  const scores = [2, 9, 1];
  expect(sortedScores(scores)).toEqual([9, 2, 1]);
  expect(scores).toEqual([2, 9, 1]);
});
